function informalToFormal(sentence) {
  // Quy tắc nâng cao: sửa chữa sự không chính thức, chữ cái lớn, và thêm dấu chấm câu
  const informalMap = {
    "i'm": "I am", "u": "you", "gotta": "have to", "wanna": "want to",
    // Thêm hơn nữa... (các cặp từ không chính thức - chính thức)
  };

  let formalSentence = sentence.toLowerCase().split(' ');
  let result = [];

  formalSentence.forEach(word => {
    const formalWord = informalMap[word] || word;  // Bản đồ thay thế / giữ nguyên từ
    result.push(formalWord.charAt(0).toUpperCase() + formalWord.slice(1));  // Capitalize each word
  });

  return result.join(' ') + '.';  // Thêm dấu chấm cuối và trả về câu chính thức
}

// Ví dụ sử dụng:
